 return '<div class="table-wrap"><table class="data-table"><thead><tr><th>Lote</th><th>Criado</th><th>Total</th><th>Concluídos</th><th>Falhas</th><th>Progresso</th><th>Status</th><th>Ações</th></tr></thead><tbody>'+items.map(function(b){var s=batchStats(b),p=Math.round((s.completed+s.failed+s.cancelled)*100/b.items.length),active=["processing","paused"].includes(b.status);return '<tr><td><strong>'+b.name+'</strong></td><td>'+date(b.createdAt)+'</td><td>'+b.items.length+'</td><td>'+s.completed+'</td><td>'+s.failed+'</td><td>'+p+'%</td><td>'+badge(b.status)+'</td><td class="row-actions"><button class="link-btn" data-batch="'+b.id+'">Detalhes</button><button class="link-btn" data-delete-batch="'+b.id+'" '+(active?"disabled title=\"Cancele ou finalize o lote antes de excluir\"":"")+'>Excluir</button></td></tr>'}).join("")+'</tbody></table></div>';
