 try{await Promise.all(Array.from({length:Math.min(5,docs.length)},worker));if(!entries.length)throw new Error("Nenhum XML pôde ser preparado. Verifique se o agente local está conectado.");download(folder.slice(0,-1)+".zip",makeZip(entries),"application/zip");audit("XMLS_EXPORTADOS",entries.length+" arquivo(s) em pasta ZIP",failures.length?"ATENÇÃO":"SUCESSO");toast(failures.length?entries.length+" XML(s) exportados; "+failures.length+" não foram encontrados":entries.length+" XML(s) exportados em uma pasta ZIP")}catch(error){toast(error.message||"Não foi possível exportar os XMLs")}finally{save();render()}
