async function downloadXml(docId){var d=state.documents.find(function(x){return x.id===docId});if(!d)return;try{if(!d.localFileId){openXmlExportConfig([d],true);return}var response=await fetch(AGENT_URL+"/api/dfe/xml",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({fileId:d.localFileId})}),data=await response.json();if(!response.ok)throw new Error(data.error||"XML não encontrado");downloadBase64(data.filename||("documento-"+d.number+".xml"),data.contentBase64,"application/xml");audit("XML_ORIGINAL_BAIXADO",d.localFileId);save()}catch(error){toast(error.message||"Não foi possível preparar o XML")}}
function openDoc(docId){var d=state.documents.find(function(x){return x.id===docId});if(!d)return;var logs=d.logs.map(function(l){return "<div>"+l+"</div>"}).join("");showModal('<div class="modal-head"><div><small>Documento '+d.number+'</small><h2>'+d.issuer+'</h2></div><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="grid detail-grid">'+detail("Chave",mask(d.accessKey))+detail("Emissão",date(d.issueDate))+detail("Valor",money(d.value))+detail("Emitente",d.issuer)+detail("Destinatário",d.recipient)+detail("Origem XML",d.xmlSource)+'</div><div class="actions" style="margin-top:18px"><button class="btn primary" data-modal-xml="'+d.id+'">'+(isRealDocument(d)?"Baixar XML original":"Baixar XML demonstrativo")+'</button></div>'+(!isRealDocument(d)?'<div class="notice" style="margin-top:14px">Registro de demonstração: não corresponde a uma nota obtida da SEFAZ e não possui PDF real.</div>':'<div class="notice" style="margin-top:14px">A SEFAZ distribui o XML oficial. O DANFE/PDF será gerado a partir desse XML em módulo separado.</div>')+'<h3 style="margin-top:24px">Histórico de processamento</h3><div class="timeline">'+logs+'</div></div>');audit("DOCUMENTO_VISUALIZADO","Documento "+d.number);save()}
function detail(l,v){return '<div class="detail"><span>'+l+'</span><strong>'+v+'</strong></div>'}
function openBatch(batchId){var b=state.batches.find(function(x){return x.id===batchId});if(!b)return;var s=batchStats(b),rows=b.items.slice(0,80).map(function(i){return '<tr><td><code>'+mask(i.accessKey)+'</code></td><td>'+LABELS[i.status]+'</td><td>'+i.attempts+'</td><td>'+(i.errorCode||"—")+'</td></tr>'}).join("");showModal('<div class="modal-head"><div><small>Detalhes do lote</small><h2>'+b.name+'</h2></div><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="grid detail-grid">'+detail("Total",b.items.length)+detail("Concluídos",s.completed)+detail("Falhas",s.failed)+'</div><div class="actions" style="margin-top:16px"><button class="btn" data-batch-csv="'+b.id+'">Exportar CSV</button></div><div class="table-wrap" style="margin-top:15px"><table class="data-table"><thead><tr><th>Chave</th><th>Etapa/status</th><th>Tentativas</th><th>Erro</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>')}
function showModal(html){var root=document.getElementById("modalRoot");root.innerHTML='<div class="modal-backdrop"><div class="modal">'+html+'</div></div>';root.querySelector("[data-close]").onclick=function(){root.innerHTML=""};root.querySelector(".modal-backdrop").onclick=function(e){if(e.target===e.currentTarget)root.innerHTML=""};var x=root.querySelector("[data-modal-xml]");if(x)x.onclick=function(){downloadXml(x.dataset.modalXml)};var p=root.querySelector("[data-demo-pdf]");if(p)p.onclick=function(){toast("PDF demonstrativo: integração real ainda não configurada")};var c=root.querySelector("[data-batch-csv]");if(c)c.onclick=function(){var b=state.batches.find(function(z){return z.id===c.dataset.batchCsv});var rows="chave;status;tentativas;erro\n"+b.items.map(function(i){return [i.accessKey,i.status,i.attempts,i.errorCode||""].join(";")}).join("\n");download(b.name.replace(/[^a-z0-9]/gi,"-")+".csv","\ufeff"+rows,"text/csv")}}
function deleteDocument(docId){var d=state.documents.find(function(x){return x.id===docId});if(!d)return;if(confirm("Excluir a chave "+mask(d.accessKey)+" e seus dados demonstrativos? Esta ação não poderá ser desfeita.")){state.documents=state.documents.filter(function(x){return x.id!==docId});delete selectedDocs[docId];audit("CHAVE_EXCLUÍDA","Documento "+d.number,"ATENÇÃO");save();toast("Chave excluída");render()}}
function clearDemonstrationDocuments(){var demos=state.documents.filter(function(d){return !isRealDocument(d)});if(!demos.length)return;if(confirm("Remover "+demos.length+" registros demonstrativos? Documentos reais da SEFAZ serão preservados.")){state.documents=state.documents.filter(isRealDocument);state.batches=[];selectedDocs={};audit("DADOS_DEMONSTRATIVOS_REMOVIDOS",demos.length+" documentos","ATENÇÃO");save();toast("Registros demonstrativos removidos");render()}}
function deleteSelectedDocuments(){var ids=Object.keys(selectedDocs).filter(function(k){return selectedDocs[k]}),count=ids.length;if(!count)return;if(confirm("Excluir "+count+" chave(s) selecionada(s) e seus dados demonstrativos?")){var map={};ids.forEach(function(x){map[x]=1});state.documents=state.documents.filter(function(d){return !map[d.id]});selectedDocs={};audit("CHAVES_EXCLUÍDAS_EM_MASSA",count+" documentos","ATENÇÃO");save();toast(count+" chave(s) excluída(s)");render()}}
function deleteBatch(batchId){var b=state.batches.find(function(x){return x.id===batchId});if(!b||["processing","paused"].includes(b.status))return;if(confirm("Excluir "+b.name+" do histórico? Os documentos e XMLs processados continuarão disponíveis.")){state.batches=state.batches.filter(function(x){return x.id!==batchId});audit("LOTE_EXCLUÍDO",b.name,"ATENÇÃO");save();toast("Lote excluído do histórico");render()}}
function clearCompletedBatches(){var removable=state.batches.filter(function(b){return !["processing","paused"].includes(b.status)});if(!removable.length)return;if(confirm("Excluir "+removable.length+" lote(s) finalizado(s) do histórico? Os documentos continuarão disponíveis.")){state.batches=state.batches.filter(function(b){return ["processing","paused"].includes(b.status)});audit("LOTES_FINALIZADOS_LIMPOS",removable.length+" lotes","ATENÇÃO");save();toast("Histórico de lotes concluídos limpo");render()}}
function retryItem(bid,iid){var b=state.batches.find(function(x){return x.id===bid}),i=b&&b.items.find(function(x){return x.id===iid});if(i){i.status="pending";i.stepIndex=0;i.errorCode=null;i.errorMessage=null;i.seed=0;b.status="processing";b.finishedAt=null;audit("ITEM_REPROCESSADO",b.name);save();startEngine();render()}}
function ignoreItem(bid,iid){var b=state.batches.find(function(x){return x.id===bid}),i=b&&b.items.find(function(x){return x.id===iid});if(i){i.status="cancelled";audit("FALHA_IGNORADA",b.name,"ATENÇÃO");save();render()}}
function retryAllFailedItems(){var rows=getFailedRows();if(!rows.length)return;if(!confirm("Reprocessar todas as "+rows.length+" falhas agora?"))return;var batches={};rows.forEach(function(x){x.i.status="pending";x.i.stepIndex=0;x.i.errorCode=null;x.i.errorMessage=null;x.i.seed=0;x.b.status="processing";x.b.finishedAt=null;batches[x.b.id]=1});audit("TODAS_FALHAS_REPROCESSADAS",rows.length+" item(ns) em "+Object.keys(batches).length+" lote(s)");save();startEngine();toast(rows.length+" falha(s) enviada(s) para reprocessamento");render()}
function ignoreAllFailedItems(){var rows=getFailedRows();if(!rows.length)return;if(!confirm("Ignorar todas as "+rows.length+" falhas? Elas sairão desta fila, mas continuarão registradas no histórico do lote."))return;rows.forEach(function(x){x.i.status="cancelled"});audit("TODAS_FALHAS_IGNORADAS",rows.length+" item(ns)","ATENÇÃO");save();toast(rows.length+" falha(s) ignorada(s)");render()}
function go(v){currentView=v;page=1;filter="";document.getElementById("sidebar").classList.remove("open");render();document.getElementById("app").focus()}
